function StatusOrdersModal({ status, request, base, close }: { status: "active" | "pending" | "pastDue"; request: ReturnType<typeof useRequest>; base: Record<string, string>; close: () => void }) {
  const [start, setStart] = useState(base.start); const [end, setEnd] = useState(base.end); const [orderId, setOrderId] = useState(""); const [repText, setRepText] = useState(""); const [managerText, setManagerText] = useState(""); const [rows, setRows] = useState<any[]>([]); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const label = status === "active" ? "Installed sales" : status === "pending" ? "Pending sales" : "Past-due installs";
  const query = (format = "") => new URLSearchParams({ ...base, start, end, status, orderId, repText, managerText, ...(format ? { format } : {}) });
  async function load() { setLoading(true); const response = await request(`/api/performance/status-orders?${query()}`); const value = await response.json(); setRows(value.rows ?? []); setTotal(value.total ?? 0); setLoading(false); }
  async function download() { const response = await request(`/api/performance/status-orders?${query("csv")}`); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `${status}-orders-${start}-to-${end}.csv`; link.click(); URL.revokeObjectURL(url); }
  useEffect(() => { void load(); }, []);
  return <div className="modal-backdrop"><section className="status-sheet"><button className="modal-close" onClick={close}>×</button><div className="panel-title"><div><h2>{label}</h2><p>{total} matching orders</p></div><button className="button primary" onClick={() => void download()}>Download CSV</button></div><div className="status-sheet-filters"><label>Start<input type="date" value={start} onChange={(event) => setStart(event.target.value)}/></label><label>End<input type="date" value={end} onChange={(event) => setEnd(event.target.value)}/></label><label>Order ID<input value={orderId} onChange={(event) => setOrderId(event.target.value)} placeholder="Contains…"/></label><label>Representative<input value={repText} onChange={(event) => setRepText(event.target.value)} placeholder="Name…"/></label><label>Manager<input value={managerText} onChange={(event) => setManagerText(event.target.value)} placeholder="Name…"/></label><button className="button secondary" onClick={() => void load()}>Apply filters</button></div><div className="table-scroll status-sheet-table"><table><thead><tr><th>ORDER</th><th>ORDER DATE</th><th>INSTALL DATE</th><th>CUSTOMER / ADDRESS</th><th>REP</th><th>MANAGER</th><th>STATUS</th></tr></thead><tbody>{loading ? <tr><td colSpan={7}>Loading orders…</td></tr> : rows.length ? rows.map((row) => <tr key={`${row.orderId}-${row.installDateId}`}><td>{row.orderId}</td><td>{row.orderDateId}</td><td>{row.installDateId || "—"}</td><td>{row.customer || "—"}</td><td>{row.representative}</td><td>{row.manager || "—"}</td><td>{row.accountStatus || "—"}</td></tr>) : <tr><td colSpan={7}>No matching orders.</td></tr>}</tbody></table></div></section></div>;
}

